-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql (la tabla enemies con la categoria fauna y la columna drops).
--
-- Enemigos de Genshin Impact: los 569 del archivo del juego, divididos en
-- jefes (61), esbirros (285, de los que 80 son elites) y fauna (223).
--
-- Fuentes:
--   Yatta (gi.yatta.moe) -> nombre y descripcion oficiales en espanol e ingles,
--     faccion, resistencias, botin, consejos de combate e imagen.
--   Datos del propio juego (AnimeGameData, de Dimbreath) -> rango.
--
-- En Genshin no hay debilidades como en Honkai: cada enemigo tiene una
-- resistencia a cada elemento (normalmente 10%). En weaknesses van los
-- elementos con resistencia negativa, y en resistances las ocho, con las
-- inmunidades marcadas. Las versiones con resistencias distintas (Abismo,
-- eventos...) quedan en variants.
--
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada.
--
-- Generado el 2026-09-15.

--
-- PARTE 3 de 4 (237 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.enemies (
  id, game_id, name, name_en, category, rank, faction, description, image_url, weaknesses, resistances, variants, skills, drops
)
values
  ('gi-enemy-25505201', 'genshin-impact', 'Guerrero Flujoafilado - Arponero', 'Flowing Blade Harpoon-Thrower', 'esbirro', 'normal', 'Humanos', 'Un guerrero procedente del origen de los manantiales, así como un centinela tribal que patrulla por zonas acuáticas y costeras.
Este guerrero lleva dos arpones y sus habilidades de caza y pesca no se deben subestimar. Dicen que, en el pasado, la gente de las tribus cazaba bestias gigantes de aletas y escamas duras como el acero usando estas habilidades.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_Fat_NoWeapon_Mosasaurus.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25502201', 'genshin-impact', 'Guerrero Flujoafilado - Serrasálmido', 'Flowing Blade Grease-Saw', 'esbirro', 'normal', 'Humanos', 'Un guerrero procedente del origen de los manantiales, así como un centinela tribal que patrulla por zonas acuáticas y costeras.
Siempre se sitúa en el frente de batalla y blande una espada con unos dientes desgarradores. Los miembros de las tribus que practican el uso de la espada lo hacen en zonas acuáticas para entrenar su fuerza y sus habilidades contra la resistencia del agua. Los mejores entre ellos son capaces de partir un pez en dos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_Male_Sword_Mosasaurus.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25505101', 'genshin-impact', 'Guerrero Forjarenas - Lanzajabalinas', 'Forged Sand Javelineer', 'esbirro', 'normal', 'Humanos', 'Un guerrero de los cañones, así como un centinela tribal que patrulla por las montañas y ríos en los que abundan las piedras preciosas.
En la época en la que las montañas habían sido destrozadas y las tribus necesitaban ser reconstruidas, los guerreros usaban jabalinas como marcas con las que determinaban las ubicaciones de ambos lados de un cañón desde las que se podían excavar nuevos caminos. Para ello, tenían que clavar muy bien las jabalinas en la roca.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_Fat_NoWeapon_Drillhead.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25504101', 'genshin-impact', 'Guerrero Forjarenas - Quebrantaescudos', 'Forged Sand Shieldbreaker', 'esbirro', 'normal', 'Humanos', 'Un guerrero de los cañones, así como un centinela tribal que patrulla por las montañas y ríos en los que abundan las piedras preciosas.
Este Guerrero Tribal lleva un martillo gigante para ir en la vanguardia y ser el primero en romper las defensas enemigas. En los Vástagos del Eco, una tribu aficionada a las gemas y la artesanía decorativa, los martillos son unas herramientas que los guerreros usaban mucho en su infancia.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_MuscleMan_Claymore_Drillhead.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25504201', 'genshin-impact', 'Guerrero Plumífero - Dominavientos', 'Winged Warrior: Skymaster', 'esbirro', 'normal', 'Humanos', 'Un centinela tribal de los acantilados que patrulla los picos montañosos más escarpados.
Estos guerreros han aprendido a dominar su propio poder al observar e imitar los golpes con garra de los saurios voladores. Nadie debería subestimar jamás sus patadas realizadas desde las alturas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_MuscleMan_Claymore_Flamingo.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25502101', 'genshin-impact', 'Guerrero Raudo - Exploracéfiros', 'Swiftstep Storm Scout', 'esbirro', 'normal', 'Humanos', 'Un guerrero de los árboles, así como un centinela tribal que patrulla por cañones y bosques con arroyos.
Dicen que, a modo de entrenamiento de combate, los miembros de las tribus que usan espadas deben pasar un día entero bajo un árbol partiendo las hojas que se le caen. Al igual que una hoja no hace ningún ruido al caer, los cortes de estos mensajeros pueden llegar cuando menos te lo esperes.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_Male_Sword_Hookwalker.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25503101', 'genshin-impact', 'Guerrero Raudo - Mensajero Filopesado', 'Swiftstep Armed Courier', 'esbirro', 'normal', 'Humanos', 'Un guerrero de los árboles, así como un centinela tribal que patrulla por cañones y bosques con arroyos.
Hay quien piensa que un mandoble es un arma demasiado pesada para que la lleve un mensajero de los Retoños Arbóreos. Sin embargo, tal vez precisamente debido a que tienen una responsabilidad tan grande, un arma con una gran capacidad de disuasión es algo absolutamente imprescindible.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_Male_Claymore_Hookwalker.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Silbato de madera del guardián","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112104.png","rareza":1},{"nombre":"Silbato de hierro del guerrero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112105.png","rareza":2},{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","rareza":3}]'::jsonb),
  ('gi-enemy-25135001', 'genshin-impact', 'Hechicera Glacial', 'Glaciomancer', 'esbirro', 'normal', 'Bestias exóticas', 'Una snegovik nacida en la nieve por amor.
Las mujeres snegovik se llaman “snegúrochkas”, y la mayoría de ellas nacen como magas capaces de manipular libremente el poder del hielo y la nieve. Cuenta la leyenda que los snegovik fueron creados con un alma incompleta y que necesitan enamorarse de un humano para alcanzar la perfección.
Ahora bien, una vez conseguido esto, ¿siguen necesitando el amor? Tal vez no.
Probablemente esa sea la razón por la que tantas historias de amor entre snegovik y humanos terminan en tragedia.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Human_Female_Staff_Snegurochka.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":30},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Cuando los seres feéricos conocidos como snegovik se sienten amenazados, se sellan en un ataúd helado.\nAl usar reacciones de Destello Estelar contra él, el ataúd helado se debilitará, con lo que podrá resquebrajarse más fácilmente con ataques Electro o Anemo.\nSi el ataúd helado no se rompe, el snegovik que haya en su interior recuperará cierta cantidad de la Vida perdida. Sin embargo, si el ataúd helado se rompe, el snegovik también acabará hecho añicos...","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Lumiesquirla etérea","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112146.png","rareza":1},{"nombre":"Quiebracristal etéreo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112147.png","rareza":2},{"nombre":"Petreoescama etérea","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112148.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010101', 'genshin-impact', 'Hilichurl', 'Hilichurl', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Su forma es similar a la humana, pero les falta inteligencia y espiritualidad. Según los registros, llevan más de mil años deambulando por estas tierras, pero no tienen civilización ni escritura.
Tras el desastre ocurrido hace medio milenio, se dispersaron por todo el mundo. Aunque no son especialmente fuertes ni saben organizarse, en ocasiones pueden provocar más de un quebradero de cabeza.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010401', 'genshin-impact', 'Hilichurl Ballestero', 'Hilichurl Shooter', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un Hilichurl que utiliza una ballesta sencilla para atacar. En realidad, los Hilichurls no poseen el nivel de habilidad necesario para fabricar ballestas, por lo que se sospecha que alguien los dirige y les proporciona armas y recursos. Los principales sospechosos son los Magos del Abismo...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","rareza":1},{"nombre":"Flecha afilada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","rareza":2},{"nombre":"Flecha veterana","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112013.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010901', 'genshin-impact', 'Hilichurl Ballestero Cryo', 'Cryo Hilichurl Shooter', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un Hilichurl que utiliza una ballesta sencilla para atacar. La punta de las flechas se ha congelado con un trozo de hielo que no se derrite. Parece que las heridas causadas por este tipo de flechas tardan mucho en cicatrizar porque el frío ralentiza la circulación de la sangre.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Ice_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","rareza":1},{"nombre":"Flecha afilada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","rareza":2},{"nombre":"Flecha veterana","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112013.png","rareza":3}]'::jsonb),
  ('gi-enemy-21011001', 'genshin-impact', 'Hilichurl Ballestero Electro', 'Electro Hilichurl Shooter', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un Hilichurl que utiliza una ballesta sencilla para atacar. La punta de las flechas se ha pulido utilizando un trozo de electrocristal, para causar una descarga eléctrica en el impacto. Se dice que los mejores ballesteros Hilichurl pueden disparar hasta cinco flechas a la vez.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Electric_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","rareza":1},{"nombre":"Flecha afilada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","rareza":2},{"nombre":"Flecha veterana","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112013.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010501', 'genshin-impact', 'Hilichurl Ballestero Pyro', 'Pyro Hilichurl Shooter', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un Hilichurl que utiliza una ballesta sencilla para atacar. La punta de las flechas está recubierta de un sustancia inflamable para quemar a su objetivo. El Musk opinaba que esto era un invento de un Hilichurl más inteligente de lo normal para cazar presas y cocinarlas a la vez.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Fire_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3},{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","rareza":1},{"nombre":"Flecha afilada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","rareza":2},{"nombre":"Flecha veterana","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112013.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010701', 'genshin-impact', 'Hilichurl Berserker', 'Hilichurl Berserker', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Para repeler a los aventureros que osan acercarse, este Hilichurl blande un mazo en llamas y carga hacia su oponente. Muchos incendios forestales son provocados por la irresponsabilidad de esta criatura.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Fire_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21011401', 'genshin-impact', 'Hilichurl con Escudo Cryo', 'Ice Shield Hilichurl Guard', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Existen pruebas que demuestran que los Hilichurls tienen una gran capacidad de adaptación al entorno. En los lugares con abundancia del elemento Cryo, son capaces de fabricar un escudo de hielo sólido para protegerse.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010301', 'genshin-impact', 'Hilichurl con Escudo de Madera', 'Wooden Shield Hilichurl Guard', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un guerrero Hilichurl con un escudo de madera. Los escudos de madera no solo proporcionan una buena defensa, sino que la tribu también los considera objetos preciosos. Se han reportado muchos casos de Hilichurls que atacan los campamentos de viajeros que están cocinando y se llevan las tapaderas de sus ollas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Se protege de los ataques con un escudo de madera que tiene atributos Dendro. Tal vez haya una manera de prenderle fuego...","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21011201', 'genshin-impact', 'Hilichurl con Escudo de Piedra', 'Rock Shield Hilichurl Guard', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un Hilichurl que vive en zonas donde abunda el elemento Geo. Su escudo impenetrable está reforzado con rocas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Se protege usando un escudo con atributos Geo (a diferencia de los escudos de madera de los Hilichurls con Escudo de Madera). Usa ataques pesados como Ataques Geo, mandobles y explosiones para romper el escudo.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21011501', 'genshin-impact', 'Hilichurl Extraño', 'Unusual Hilichurl', 'esbirro', 'normal', 'Hilichurls', '“Homu, Homu, mimi domu!”', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Wei.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-21011301', 'genshin-impact', 'Hilichurl Granadero Cryo', 'Cryo Hilichurl Grenadier', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Los Slimes Cryo son muy útiles para conservar la frescura de los alimentos. Los Hilichurls aprovechan los Slimes para muchas cosas, como hacer barriles explosivos con Slimes Pyro y Slimes Cryo e inventar nuevos métodos de transporte con Slimes Anemo. Quizás la dureza de su modo de vida les proporcionó esta capacidad innovadora.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Ice_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010201', 'genshin-impact', 'Hilichurl Guerrero', 'Hilichurl Fighter', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un guerrero tribal de mal carácter que cree en el poder de la fuerza bruta. Con los suficientes músculos y la fuerza necesaria, tal vez algún día pueda sostener un gran escudo y convertirse en un Mitachurl.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_None_01.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21010601', 'genshin-impact', 'Hilichurl Lanzagranadas', 'Hilichurl Grenadier', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Un Hilichurl experto en utilizar Slimes Pyro como armas para atacar a sus enemigos. Un lanzagranadas habilidoso puede derribar hasta cinco postes de madera con una sola explosión de un Slime Pyro.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Fire_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","rareza":1},{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","rareza":2},{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","rareza":3}]'::jsonb),
  ('gi-enemy-21011601', 'genshin-impact', 'Hilichurl Lanzagranadas Electro', 'Electro Hilichurl Grenadier', 'esbirro', 'normal', 'Hilichurls', 'Los habitantes primitivos de Teyvat.
Para los Hilichurls， que conservan un estilo de vida primitivo, los Slimes Electro no tienen una gran variedad de usos como los Slimes Pyro o Anemo. ¿Quizás algún día dominen el flujo de energía que hay entre Slimes Electro y Slimes Mutantes Electro y tengan un desarrollo agigantado?', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Hili_Electric_Range.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, null),
  ('gi-enemy-26120301', 'genshin-impact', 'Hydrohongo Terrestre', 'Grounded Hydroshroom', 'esbirro', 'normal', 'Bestias exóticas', 'Una criatura fúngica mimética que posee una gran capacidad de adaptación al entorno.
Se parece a un pájaro, pero no parece haber desarrollado la habilidad para volar. Tal vez sea por la influencia del elemento Hydro, pero es extremadamente ágil en comparación con otras criaturas. Algunos estudios abogan por que no se trata de un organismo, sino que está formado por innumerables estructuras fúngicas de pequeño tamaño.
Dentro del ecosistema fúngico, ocupa una posición de poder y parece tener una capacidad intelectual superior a la del resto de Hongos.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Fungus_Amanita_Du_Anudatta_Water.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":30},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":30},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[{"nombre":"Consejo de combate","descripcion":"Un monstruo de inteligencia muy básica que evolucionó desde las esporas. La primera vez que reciba un ataque Electro o Pyro, entrará en el estado de revitalizado o de quemado dependiendo del tipo elemental del ataque. Derrota a este hongo evolucionado y encontrarás todo tipo de botines.","tipo":"consejo","elemento":null}]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Espora fúngica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112059.png","rareza":1},{"nombre":"Polen fluorescente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112060.png","rareza":2},{"nombre":"Polvo quistecristalino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112061.png","rareza":3},{"nombre":"Núcleo fúngico inerte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112062.png","rareza":2},{"nombre":"Núcleo fúngico inactivo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112063.png","rareza":3},{"nombre":"Núcleo fúngico robusto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112064.png","rareza":4}]'::jsonb),
  ('gi-enemy-26240201', 'genshin-impact', 'Iktomisaurio', 'Iktomisaurus', 'esbirro', 'normal', 'Bestias exóticas', 'Un saurio capaz de aprovechar su plumaje para realizar poderosos saltos. Los Iktomisaurios también son la única especie de saurio que ha aprendido a entrar en un estado de espiritismo.
Según cuenta la leyenda, sus ancestros no poseían una forma física y, en su lugar, podían vagar como espíritus entre la realidad y el mundo esotérico, eligiendo manifestarse a través de la oscuridad de la noche. Algunos dicen también que el primer Iktomisaurio que surgió del Reino de la Noche no era un verdadero saurio, sino una especie completamente distinta al resto.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Natsaurus_Shamansaurus_Normal.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":50},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","rareza":1},{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","rareza":2},{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","rareza":3}]'::jsonb),
  ('gi-enemy-26210201', 'genshin-impact', 'Koholasaurio', 'Koholasaurus', 'esbirro', 'normal', 'Bestias exóticas', 'Un saurio con unas aletas muy toscas y una larga cola, capaz de moverse por el agua y el flogisto líquido.
Cuenta la leyenda que los dragones de la antigüedad tenían una mayor capacidad de adaptación al entorno, de manera que, al flotar en la superficie del agua, los dragones marinos más grandes se podían confundir con islas enteras. Los Koholasaurio de ahora serían los descendientes de aquellos gigantescos dragones marinos. De hecho, a partir de sus amplias espaldas, nos podemos hacer una idea de lo colosales que debieron de ser aquellas bestias marinas de la antigüedad.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Natsaurus_Mosasaurus_Normal.png', '[]'::jsonb, '[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":50},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","rareza":1},{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","rareza":2},{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","rareza":3}]'::jsonb),
  ('gi-enemy-25070101', 'genshin-impact', 'Ladrón de Tesoros - Aplastador', 'Treasure Hoarders: Crusher', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
Antes trabajaban de mineros. Cuando se cerró la Sima, tomaron su asignación y se unieron a los Ladrones de Tesoros.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_MuscleMan_Miner_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25030201', 'genshin-impact', 'Ladrón de Tesoros - Asaltante de Tumbas', 'Treasure Hoarders: Gravedigger', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
“Ponerse sobre los hombros de gigantes quiere decir que recogemos la riqueza acumulada por quienes vinieron antes que nosotros y nos la llevamos para... ¡devolverla al ciclo de la economía! ¡Qué empresa tan noble!”
Eso dijo un Asaltante de Tumbas de los Ladrones de Tesoros mientras excavaba en unas ruinas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Rogue_Fat_02.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25020201', 'genshin-impact', 'Ladrón de Tesoros - Ballestero', 'Treasure Hoarders: Marksman', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
A veces los llaman “arqueros divinos” para reírse de ellos. A fin de cuentas, el arma que utiliza es la ballesta, no el arco, que requiere de años de práctica. ¡Hasta los Hilichurls saben usar ballestas! Lo único que hay que hacer es apuntar al enemigo con la parte más ancha, apretar el gatillo, y ¡bam!, ya está.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Hunter_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25060101', 'genshin-impact', 'Ladrón de Tesoros - Boxeador', 'Treasure Hoarders: Pugilist', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
Aficionados a los músculos y a pelear. Son muy quisquillosos con la comida y siempre están presumiendo de las ventajas de ser musculoso, por lo que los demás Ladrones de Tesoros no los tienen en demasiada estima.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_MuscleMan_Boxer_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25010201', 'genshin-impact', 'Ladrón de Tesoros - Centinela', 'Treasure Hoarders: Scout', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
Con frecuencia se encarga de vigilar. Normalmente, la senda criminal se suele elegir debido a la pobreza o a la falta de formación, como la única forma de enriquecerse. No obstante, a juzgar por su equipamiento, los miembros de esta organización no han conseguido hacerse ricos ni robando...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Rogue_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, '[{"debilidades":["Físico"],"resistencias":[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]},{"debilidades":[],"resistencias":[{"elemento":"Físico","valor":10},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]}]'::jsonb, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25030301', 'genshin-impact', 'Ladrón de Tesoros - Grumete', 'Treasure Hoarders: Seaman', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
“¿Cómo pueden decir que lo que hacemos es robar? ¿O expoliar? ¡Lo que hacemos es volver a descubrir y devolver los tesoros a las manos de quienes saben apreciarlos! ¡Así todos están contentos! ¡Todo son ventajas!”
Eso le dijo un Grumete de los Ladrones de Tesoros a un nuevo miembro que tenía dudas.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Sailor_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25010601', 'genshin-impact', 'Ladrón de Tesoros - Maestro de Pociones Cryo', 'Treasure Hoarders: Cryo Potioneer', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
Los Maestros de Pociones Cryo son bastante populares entre los Ladrones de Tesoros porque las pócimas que preparan pueden reducir la temperatura rápidamente. Así se pueden preparar bebidas frías hasta cuando no hay flores heladas por los alrededores.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Chemist_Ice_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25010501', 'genshin-impact', 'Ladrón de Tesoros - Maestro de Pociones Electro', 'Treasure Hoarders: Electro Potioneer', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
“Maestro de Pociones” es como llaman los Ladrones de Tesoros a los miembros que se encargan de mezclar sustancias químicas peligrosas.
“¿Qué dices? ¿Acaso en este tesoro pone «Propiedad del Gremio de Aventureros»?”.
Eso le dijo un Maestro de Pociones de los Ladrones de Tesoros a un aventurero durante un enfrentamiento.', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Chemist_Electric_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25010401', 'genshin-impact', 'Ladrón de Tesoros - Maestro de Pociones Hydro', 'Treasure Hoarders: Hydro Potioneer', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
Se dice que, antes de unirse a los Ladrones de Tesoros, algunos de estos Maestros de Pociones eran estafadores que iban vendiendo sus “pociones” y su “agua bendita” por las aldeas. Estos mejunjes parecen dar un mejor resultado en el campo de batalla...', 'https://gi.yatta.moe/assets/UI/monster/UI_MonsterIcon_Thoarder_Male_Chemist_Water_01.png', '["Físico"]'::jsonb, '[{"elemento":"Físico","valor":-20},{"elemento":"Pyro","valor":10},{"elemento":"Hydro","valor":10},{"elemento":"Anemo","valor":10},{"elemento":"Electro","valor":10},{"elemento":"Dendro","valor":10},{"elemento":"Cryo","valor":10},{"elemento":"Geo","valor":10}]'::jsonb, null, '[]'::jsonb, '[{"nombre":"Mora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_202.png","rareza":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","rareza":1},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","rareza":2},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","rareza":3}]'::jsonb),
  ('gi-enemy-25010301', 'genshin-impact', 'Ladrón de Tesoros - Maestro de Pociones Pyro', 'Treasure Hoarders: Pyro Potioneer', 'esbirro', 'normal', 'Humanos', 'Un miembro de un grupo poco organizado que ha llegado a todos los rincones del continente, incluso a dominios desconocidos.
